      "id": "xeon-template-108",
      "sourceId": 108,
      "eventType": "IssueTrackerResolution",
      "recipientRole": "",
      "communicationMode": "Email",
      "code": "IssueTrackerResolution",
      "subject": "Issue Tracker - Resolution",
      "schedule": "Instant",
      "description": "",
      "body": "<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <title>Action Required - Inebura</title>\r\n</head>\r\n\r\n<body\r\n    style=\"font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background-color: #f5f7fa; margin: 0; padding: 0; color: #333;\">\r\n    <div\r\n        style=\"max-width: 600px; margin: auto; background: #ffffff; box-shadow: 0 0 10px rgba(0,0,0,0.05); border-radius: 8px; overflow: hidden;\">\r\n         <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"background-color: #d0c3f1;\">\r\n      <tr>\r\n          <td style=\"width: 48%; text-align: center; vertical-align: middle; padding: 15px 20px;\">\r\n              <img src=\"https://public-inebura.s3.ap-south-1.amazonaws.com/logos/inebura_logo.png\"\r\n                  alt=\"Inebura Logo\" height=\"60\" style=\"max-height: 60px; width: auto;\">\r\n          </td>\r\n          <td style=\"width: 4%; text-align: center; vertical-align: middle; padding: 10px 0;\">\r\n              <div style=\"width: 2px; height: 60px; background-color: rgba(255,255,255,0.6); margin: 0 auto; border-radius: 1px;\"></div>\r\n          </td>\r\n          <td style=\"width: 48%; text-align: center; vertical-align: middle; padding: 15px 20px;\">\r\n              <img src=\"${clientLogo}\" alt=\"Client Logo\" height=\"60\"\r\n                  style=\"border-radius: 6px; max-height: 60px; width: auto; max-width: 150px;\">\r\n          </td>\r\n      </tr>\r\n  </table>\r\n        <div style=\"padding: 30px;\">\r\n            <p>Dear ${clientFullName},</p>\r\n            <p>${kam} has provided resolution on the below mentioned issue(s)</p>\r\n            <div style=\"overflow-x:auto; margin-top: 20px;\">\r\n                <table border=\"1\" cellspacing=\"0\" cellpadding=\"6\" style=\"width: 100%; border-collapse: collapse; font-size: 12px; table-layout: fixed; word-wrap: break-word; word-break: break-word; overflow-wrap: anywhere;\">\r\n    <colgroup>\r\n    <col style=\"width: 16%;\">\r\n    <col style=\"width: 12%;\">\r\n    <col style=\"width: 12%;\">\r\n    <col style=\"width: 12%;\">\r\n    <col style=\"width: 12%;\">\r\n    <col style=\"width: 12%;\">\r\n    <col style=\"width: 12%;\">\r\n    <col style=\"width: 12%;\">\r\n    </colgroup>\r\n    <tr style=\"background-color: #f1f4f9; font-weight: bold;\">\r\n        <th style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; text-align: left;\">Client Name</th>\r\n        <th style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; text-align: left;\">Customer Name</th>\r\n        <th style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; text-align: left;\">Customer Code</th>\r\n        <th style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; text-align: left;\">Assignee</th>\r\n        <th style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; text-align: left;\">Invoice No</th>\r\n        <th style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; text-align: left;\">Issue</th>\r\n        <th style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; text-align: left;\">Remarks</th>\r\n        <th style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; text-align: left;\">Action Owners</th>\r\n    </tr>\r\n    <#list listOfInvoices as invoiceList>\r\n    <tr>\r\n        <td style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; vertical-align: top;\">${invoiceList.clientName}</td>\r\n        <td style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; vertical-align: top;\">${invoiceList.customerName}</td>\r\n        <td style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; vertical-align: top;\">${invoiceList.customerCode}</td>\r\n        <td style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; vertical-align: top;\">${invoiceList.assignee}</td>\r\n        <td style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; vertical-align: top;\">${invoiceList.invoiceNo}</td>\r\n        <td style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; vertical-align: top;\">${invoiceList.issue}</td>\r\n        <td style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; vertical-align: top;\">${invoiceList.latestRemarks}</td>\r\n        <td style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; vertical-align: top;\">${invoiceList.actionOwners}</td>\r\n    </tr>\r\n    </#list>\r\n</table>\r\n            </div>\r\n            <div\r\n                style=\"margin-top: 20px; background-color: #fff3cd; padding: 12px; border-left: 4px solid #ffc107; border-radius: 4px;\">\r\n                <strong>Note:</strong> To view the invoices where we need your intervention please click on the below\r\n                link. You can provide your feedback and attach the concerned documents there</div>\r\n            <div style=\"text-align: center; margin-top: 25px;\"><a\r\n                    href=\"https://${subdomain}.inebura.ai/intg/action-owner-link/${token}\"\r\n                    style=\"display: inline-block; background-color: #0049b7; color: #fff; padding: 12px 24px; text-decoration: none; border-radius: 5px; font-weight: bold;\">View\r\n                    & Take Action</a></div>\r\n            <p style=\"margin-top: 30px;\">Regards,<br><strong>Admin</strong></p>\r\n        </div>\r\n        <div style=\"padding: 15px; text-align: center; font-size: 13px; color: #777; background-color: #f9f9f9;\">&copy;\r\n            Inebura Technologies. All rights reserved.</div>\r\n    </div>\r\n</body>\r\n\r\n</html>",
      "notificationBody": "",
      "disabled": false,
      "attachmentApplicable": null
