      "body": "<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <title>You're Invited - Inebura</title>\r\n</head>\r\n\r\n<body style=\"font-family:'Segoe UI',Tahoma,Geneva,Verdana,sans-serif;background:#f5f7fa;margin:0;padding:0;color:#333;\">\r\n    <div\r\n        style=\"max-width:600px;margin:auto;background:#fff;box-shadow:0 0 10px rgba(0,0,0,0.05);border-radius:8px;overflow:hidden;\">\r\n  <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"background-color: #d0c3f1;\">\r\n      <tr>\r\n          <td style=\"width: 48%; text-align: center; vertical-align: middle; padding: 15px 20px;\">\r\n              <img src=\"https://public-inebura.s3.ap-south-1.amazonaws.com/logos/inebura_logo.png\"\r\n                  alt=\"Inebura Logo\" height=\"60\" style=\"max-height: 60px; width: auto;\">\r\n          </td>\r\n          <td style=\"width: 4%; text-align: center; vertical-align: middle; padding: 10px 0;\">\r\n              <div style=\"width: 2px; height: 60px; background-color: rgba(255,255,255,0.6); margin: 0 auto; border-radius: 1px;\"></div>\r\n          </td>\r\n          <td style=\"width: 48%; text-align: center; vertical-align: middle; padding: 15px 20px;\">\r\n              <img src=\"${clientLogo}\" alt=\"Client Logo\" height=\"60\"\r\n                  style=\"border-radius: 6px; max-height: 60px; width: auto; max-width: 150px;\">\r\n          </td>\r\n      </tr>\r\n  </table>\r\n        <div style=\"padding:30px;\">\r\n            <h3>You're invited to Inebura Ops!</h3>\r\n            <p>Hi,</p>\r\n            <p><b>${assignee}</b> has invited you to join <b>${userClient}</b> on <b>Inebura Ops</b> — the intelligent\r\n                platform for managing accounts receivable, customer relationships, and collections workflows.</p>\r\n            <p>Click the button below to set up your account. This invitation link will expire in <b>48 hours</b>.</p>\r\n            <div style=\"margin-top:20px;border:1px solid #e0e0e0;border-radius:6px;overflow:hidden;\">\r\n                <table style=\"width:100%;border-collapse:collapse;font-size:14px;\">\r\n                    <tr style=\"background:#f7f8fb;\">\r\n                        <td style=\"padding:10px;font-weight:bold;width:40%;\">Invited By</td>\r\n                        <td style=\"padding:10px;\">${assignee}</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td style=\"padding:10px;font-weight:bold;\">Organisation</td>\r\n                        <td style=\"padding:10px;\">${userClient}</td>\r\n                    </tr>\r\n                    <tr style=\"background:#f7f8fb;\">\r\n                        <td style=\"padding:10px;font-weight:bold;\">Assigned Role</td>\r\n                        <td style=\"padding:10px;\">${UserRole}</td>\r\n                    </tr>\r\n                </table>\r\n            </div>\r\n            <div style=\"margin-top:20px;\"><b>With Inebura Ops you can:</b>\r\n                <ul style=\"margin-top:8px;\">\r\n                    <li>Track receivables and payments</li>\r\n                    <li>Manage customers and credit limits</li>\r\n                    <li>Automate collections workflow</li>\r\n                    <li>Collaborate with your team</li>\r\n                </ul>\r\n            </div>\r\n            <div style=\"margin-top:20px;background:#fff3cd;padding:12px;border-left:4px solid #ffc107;\"><strong>Action\r\n                    Required:</strong> Please accept the invitation using the button below.</div>\r\n            <div style=\"text-align:center;margin-top:25px;\"><a\r\n                    href=\"https://${subDomain}.inebura.ai/invite/${emailId}/${userId}\"\r\n                    style=\"background:#0049b7;color:#fff;padding:12px 24px;text-decoration:none;border-radius:5px;font-weight:bold;\">Accept\r\n                    Invitation</a></div>\r\n            <p style=\"margin-top:20px;font-size:13px;\">If button doesn't\r\n                work:<br>https://${subDomain}.inebura.ai/invite/${emailId}/${userId}</p>\r\n            <p style=\"margin-top:30px;\">Regards,<br><b>Inebura System</b></p>\r\n            <p style=\"font-size:12px;color:#777;\">Need help? support@inebura.ai<br>If you didn't expect this invitation,\r\n                ignore this email.</p>\r\n        </div>\r\n        <div style=\"padding:15px;text-align:center;font-size:13px;color:#777;background:#f9f9f9;\">© 2026 Inebura Ops.\r\n            All rights reserved.</div>\r\n    </div>\r\n</body>\r\n\r\n</html>",
