      "schedule": "Instant",
      "description": "",
      "body": "<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <title>Approval Required - Inebura</title>\r\n</head>\r\n\r\n<body\r\n    style=\"font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background-color: #f5f7fa; margin: 0; padding: 0; color: #333;\">\r\n    <div\r\n        style=\"max-width: 600px; margin: auto; background: #ffffff; box-shadow: 0 0 10px rgba(0,0,0,0.05); border-radius: 8px; overflow: hidden;\">\r\n         <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"background-color: #d0c3f1;\">\r\n      <tr>\r\n          <td style=\"width: 48%; text-align: center; vertical-align: middle; padding: 15px 20px;\">\r\n              <img src=\"https://public-inebura.s3.ap-south-1.amazonaws.com/logos/inebura_logo.png\"\r\n                  alt=\"Inebura Logo\" height=\"60\" style=\"max-height: 60px; width: auto;\">\r\n          </td>\r\n          <td style=\"width: 4%; text-align: center; vertical-align: middle; padding: 10px 0;\">\r\n              <div style=\"width: 2px; height: 60px; background-color: rgba(255,255,255,0.6); margin: 0 auto; border-radius: 1px;\"></div>\r\n          </td>\r\n          <td style=\"width: 48%; text-align: center; vertical-align: middle; padding: 15px 20px;\">\r\n              <img src=\"${clientLogo}\" alt=\"Client Logo\" height=\"60\"\r\n                  style=\"border-radius: 6px; max-height: 60px; width: auto; max-width: 150px;\">\r\n          </td>\r\n      </tr>\r\n  </table>\r\n        <div style=\"padding: 30px;\">\r\n            <p>Dear ${managerName},</p>\r\n            <p>Agent <b>${agentName}</b> has created issue request for the below invoice(s). Your approval is required\r\n                to proceed further.</p>\r\n            <div style=\"overflow-x:auto; margin-top: 20px;\">\r\n                <table border=\"1\" cellspacing=\"0\" cellpadding=\"8\"\r\n                    style=\"width: 100%; border-collapse: collapse; font-size: 14px;\">\r\n                    <tr style=\"background-color: #f1f4f9; font-weight: bold;\">\r\n                        <th>Client Name</th>\r\n                        <th>Customer Name</th>\r\n                        <th>Customer Code</th>\r\n                        <th>Invoice No</th>\r\n                        <th>Issue</th>\r\n                        <th>Remarks</th>\r\n                        <th>Created By</th>\r\n                    </tr>\r\n                    <#list listOfInvoices as invoiceList>\r\n                        <tr>\r\n                            <td>${invoiceList.clientName}</td>\r\n                            <td>${invoiceList.customerName}</td>\r\n                            <td>${invoiceList.customerCode}</td>\r\n                            <td>${invoiceList.invoiceNo}</td>\r\n                            <td>${invoiceList.issue}</td>\r\n                            <td>${invoiceList.latestRemarks}</td>\r\n                            <td>${invoiceList.createdBy}</td>\r\n                        </tr>\r\n                    </#list>\r\n                </table>\r\n            </div>\r\n            <div\r\n                style=\"margin-top: 20px; background-color: #fff3cd; padding: 12px; border-left: 4px solid #ffc107; border-radius: 4px;\">\r\n                <strong>Action Required:</strong> Please review the request and provide your approval by clicking the\r\n                button below.</div>\r\n            <div style=\"text-align: center; margin-top: 25px;\"><a\r\n                    href=\"https://${subdomain}.inebura.ai/dashboard/issue-tracker\"\r\n                    style=\"display: inline-block; background-color: #0049b7; color: #fff; padding: 12px 24px; text-decoration: none; border-radius: 5px; font-weight: bold;\">Review\r\n                    & Approve</a></div>\r\n            <p style=\"margin-top: 30px;\">Regards,<br><strong>Inebura System</strong></p>\r\n        </div>\r\n        <div style=\"padding: 15px; text-align: center; font-size: 13px; color: #777; background-color: #f9f9f9;\">©\r\n            Inebura Technologies. All rights reserved.</div>\r\n    </div>\r\n</body>\r\n\r\n</html>",
