      "notificationBody": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"UTF-8\"><title>Test Email - Inebura</title></head><body style=\"font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background-color: #f5f7fa; margin: 0; padding: 0; color: #333;\"><div style=\"max-width: 600px; margin: auto; background: #ffffff; box-shadow: 0 0 10px rgba(0,0,0,0.05); border-radius: 8px; overflow: hidden;\"><div style=\"background-color: #d0c3f1; padding: 20px; text-align: center;\"><img src=\"https://public-inebura.s3.ap-south-1.amazonaws.com/logos/inebura_logo.png\" alt=\"Inebura Logo\" style=\"max-height: 60px;\"></div><div style=\"padding: 30px; text-align: center;\"><h2 style=\"color: #0049b7; margin-top: 0;\">This is a Test Email</h2><p style=\"font-size: 16px;\">Hello,</p><p style=\"font-size: 16px;\">This is a test email sent from the Inebura system to verify that your email service is working correctly.</p><p style=\"font-size: 16px;\">No action is required on your part.</p><p style=\"margin-top: 30px;\">Regards,<br><strong>Inebura Admin</strong></p></div><div style=\"padding: 15px; text-align: center; font-size: 13px; color: #777; background-color: #f9f9f9;\">&copy; Inebura Technologies. All rights reserved.</div></div></body></html>",
