      "body": "<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <title>OTP Verification - Inebura</title>\r\n</head>\r\n\r\n<body\r\n    style=\"margin:0; padding:0; background-color:#f5f7fa; font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; color:#333;\">\r\n    <div\r\n        style=\"max-width: 600px; margin: auto; background: #ffffff; box-shadow: 0 0 10px rgba(0,0,0,0.05); border-radius: 8px; overflow: hidden;\">\r\n        <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\"\r\n        style=\"background-color:#f5f7fa; padding:20px 0;\">\r\n        <tr>\r\n            <td align=\"center\">\r\n                <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"600\"\r\n                    style=\"background:#ffffff; border-radius:8px; box-shadow:0 0 10px rgba(0,0,0,0.05); overflow:hidden;\">\r\n\r\n                    <!-- Header -->\r\n                    <!-- <tr>\r\n            <td align=\"center\" style=\"background-color:#d0c3f1; padding:20px;\">\r\n              <img src=\"https://public-inebura.s3.ap-south-1.amazonaws.com/logos/inebura_logo.png\" alt=\"Inebura Logo\"\r\n                style=\"max-height:60px; display:block;\">\r\n            </td>\r\n          </tr> -->\r\n <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"background-color: #d0c3f1;\">\r\n      <tr>\r\n          <td style=\"width: 48%; text-align: center; vertical-align: middle; padding: 15px 20px;\">\r\n              <img src=\"https://public-inebura.s3.ap-south-1.amazonaws.com/logos/inebura_logo.png\"\r\n                  alt=\"Inebura Logo\" height=\"60\" style=\"max-height: 60px; width: auto;\">\r\n          </td>\r\n          <td style=\"width: 4%; text-align: center; vertical-align: middle; padding: 10px 0;\">\r\n              <div style=\"width: 2px; height: 60px; background-color: rgba(255,255,255,0.6); margin: 0 auto; border-radius: 1px;\"></div>\r\n          </td>\r\n          <td style=\"width: 48%; text-align: center; vertical-align: middle; padding: 15px 20px;\">\r\n              <img src=\"${clientLogo}\" alt=\"Client Logo\" height=\"60\"\r\n                  style=\"border-radius: 6px; max-height: 60px; width: auto; max-width: 150px;\">\r\n          </td>\r\n      </tr>\r\n  </table>\r\n\r\n                    <!-- Content -->\r\n                    <tr>\r\n                        <td style=\"padding:30px;\">\r\n                            <h2 style=\"color:#0049b7; margin:0 0 20px 0; font-size:22px;\">OTP Verification</h2>\r\n                            <p style=\"margin:0 0 15px 0;\">Dear <strong>${userName}</strong>,</p>\r\n                            <p style=\"margin:0 0 15px 0;\">Your OTP token for <strong>deleting</strong> client\r\n                                <strong>${clientName}</strong> is:\r\n                            </p>\r\n\r\n                            <!-- OTP Box -->\r\n                            <div\r\n                                style=\"background-color:#f1f4f9; padding:15px; border-radius:5px; text-align:center; font-size:20px; font-weight:bold; color:#0049b7; margin:20px 0;\">\r\n                                ${emailOtp}\r\n                            </div>\r\n\r\n                            <!-- Warning -->\r\n                            <div\r\n                                style=\"background-color:#fff3cd; padding:12px; border-left:4px solid #ffc107; border-radius:4px; margin-top:20px; font-size:14px; line-height:1.5;\">\r\n                                By providing this OTP, you confirm that you agree to permanently remove the client from\r\n                                the platform. <br>\r\n                                <strong>\r\n                                    &#9888;&#65039;\r\n                                    Please note:</strong> This is an *irrevocable* process and cannot be undone.\r\n                                client form INEBURA completely.\r\n                            </div>\r\n\r\n                            <p style=\"margin-top:30px;\">Best regards,<br><strong>Inebura Admin Team</strong></p>\r\n                        </td>\r\n                    </tr>\r\n\r\n                    <!-- Footer -->\r\n                    <tr>\r\n                        <td align=\"center\" style=\"background-color:#f9f9f9; padding:15px; font-size:13px; color:#777;\">\r\n                            &copy; Inebura Technologies. All rights reserved.\r\n                        </td>\r\n                    </tr>\r\n\r\n                </table>\r\n            </td>\r\n        </tr>\r\n    </table>\r\n    </div>\r\n</body>\r\n\r\n</html>",
      "notificationBody": "<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <title>OTP Verification - Inebura</title>\r\n</head>\r\n\r\n<body\r\n  style=\"margin:0; padding:0; background-color:#f5f7fa; font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; color:#333;\">\r\n  <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\"\r\n    style=\"background-color:#f5f7fa; padding:20px 0;\">\r\n    <tr>\r\n      <td align=\"center\">\r\n        <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"600\"\r\n          style=\"background:#ffffff; border-radius:8px; box-shadow:0 0 10px rgba(0,0,0,0.05); overflow:hidden;\">\r\n\r\n          <!-- Header -->\r\n          <tr>\r\n            <td align=\"center\" style=\"background-color:#d0c3f1; padding:20px;\">\r\n              <img src=\"https://public-inebura.s3.ap-south-1.amazonaws.com/logos/inebura_logo.png\" alt=\"Inebura Logo\"\r\n                style=\"max-height:60px; display:block;\">\r\n            </td>\r\n          </tr>\r\n\r\n          <!-- Content -->\r\n          <tr>\r\n            <td style=\"padding:30px;\">\r\n              <h2 style=\"color:#0049b7; margin:0 0 20px 0; font-size:22px;\">OTP Verification</h2>\r\n              <p style=\"margin:0 0 15px 0;\">Dear <strong>${userName}</strong>,</p>\r\n              <p style=\"margin:0 0 15px 0;\">Your OTP token for <strong>deleting</strong> client\r\n                <strong>${clientName}</strong> is:</p>\r\n\r\n              <!-- OTP Box -->\r\n              <div\r\n                style=\"background-color:#f1f4f9; padding:15px; border-radius:5px; text-align:center; font-size:20px; font-weight:bold; color:#0049b7; margin:20px 0;\">\r\n                ${emailOtp}\r\n              </div>\r\n\r\n              <!-- Warning -->\r\n              <div\r\n                style=\"background-color:#fff3cd; padding:12px; border-left:4px solid #ffc107; border-radius:4px; margin-top:20px; font-size:14px; line-height:1.5;\">\r\n               By providing this OTP, you confirm that you agree to permanently remove the client from the platform. <br>\r\n                <strong>\r\n                  &#9888;&#65039;\r\n                  Please note:</strong> This is an *irrevocable* process and cannot be undone. \r\n client form INEBURA completely.\r\n              </div>\r\n\r\n              <p style=\"margin-top:30px;\">Best regards,<br><strong>Inebura Admin Team</strong></p>\r\n            </td>\r\n          </tr>\r\n\r\n          <!-- Footer -->\r\n          <tr>\r\n            <td align=\"center\" style=\"background-color:#f9f9f9; padding:15px; font-size:13px; color:#777;\">\r\n              &copy; Inebura Technologies. All rights reserved.\r\n            </td>\r\n          </tr>\r\n\r\n        </table>\r\n      </td>\r\n    </tr>\r\n  </table>\r\n</body>\r\n\r\n</html>",
