      "body": "<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <title>User Account Created - Inebura</title>\r\n</head>\r\n\r\n<body style=\"font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background-color: #f5f7fa; margin: 0; padding: 0; color: #333;\">\r\n    <div style=\"max-width: 600px; margin: auto; background: #ffffff; box-shadow: 0 0 10px rgba(0,0,0,0.05); border-radius: 8px; overflow: hidden;\">\r\n        \r\n        <!-- Header -->\r\n       <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"background-color: #d0c3f1;\">\r\n      <tr>\r\n          <td style=\"width: 48%; text-align: center; vertical-align: middle; padding: 15px 20px;\">\r\n              <img src=\"https://public-inebura.s3.ap-south-1.amazonaws.com/logos/inebura_logo.png\"\r\n                  alt=\"Inebura Logo\" height=\"60\" style=\"max-height: 60px; width: auto;\">\r\n          </td>\r\n          <td style=\"width: 4%; text-align: center; vertical-align: middle; padding: 10px 0;\">\r\n              <div style=\"width: 2px; height: 60px; background-color: rgba(255,255,255,0.6); margin: 0 auto; border-radius: 1px;\"></div>\r\n          </td>\r\n          <td style=\"width: 48%; text-align: center; vertical-align: middle; padding: 15px 20px;\">\r\n              <img src=\"${clientLogo}\" alt=\"Client Logo\" height=\"60\"\r\n                  style=\"border-radius: 6px; max-height: 60px; width: auto; max-width: 150px;\">\r\n          </td>\r\n      </tr>\r\n  </table>\r\n        \r\n        <!-- Content -->\r\n        <div style=\"padding: 30px;\">\r\n            <h2 style=\"color: #0049b7; margin-top: 0;\">Welcome to Inebura!</h2>\r\n            <p>Hello,</p>\r\n            <p>We’re excited to inform you that a new account has been successfully created for you in <strong>Inebura</strong>.</p>\r\n            \r\n            <!-- Credentials -->\r\n            <div style=\"background-color: #f1f4f9; padding: 15px; border-radius: 5px; margin-top: 20px;\">\r\n                <p style=\"margin: 0;\"><strong>User Name:</strong> ${userName}</p>\r\n                <p style=\"margin: 0;\"><strong>Login ID:</strong> ${loginUserId}</p>\r\n                <p style=\"margin: 0;\"><strong>Temporary Password:</strong> ${tempPassKey}</p>\r\n                <p style=\"margin: 0;\"><strong>Client URL :  <a href=\"https://${clientSubDomain}\" >https://${clientSubDomain}</a>\r\n            </div>\r\n            \r\n            <!-- Note -->\r\n            <div style=\"margin-top: 20px; background-color: #fff3cd; padding: 12px; border-left: 4px solid #ffc107; border-radius: 4px;\">\r\n                <strong>Note:</strong> Please log in and change your password as soon as possible. Complete onboarding within <strong>7 days</strong>.\r\n            </div>\r\n            \r\n            <!-- Login Button -->\r\n            <div style=\"text-align: center; margin-top: 25px;\">\r\n                <a href=\"https://${clientSubDomain}\" \r\n                   style=\"display: inline-block; background-color: #0049b7; color: #fff; padding: 12px 24px; text-decoration: none; border-radius: 5px; font-weight: bold;\">\r\n                   Login to Your Account\r\n                </a>\r\n            </div>\r\n            \r\n            <p style=\"margin-top: 30px;\">Best regards,<br><strong>Inebura Admin Team</strong></p>\r\n        </div>\r\n        \r\n        <!-- Footer -->\r\n        <div style=\"padding: 15px; text-align: center; font-size: 13px; color: #777; background-color: #f9f9f9;\">\r\n            &copy; Inebura Technologies. All rights reserved.\r\n        </div>\r\n    </div>\r\n</body>\r\n\r\n</html>\r\n",
