      "code": "paymentAdviceToClient",
      "subject": "Payment Advice",
      "schedule": "Instant",
      "description": "",
      "body": "<html> \r\n<head></head>\r\n<body>\r\n<p>Dear ${clientFullName},</p>\r\n<p>A payment has been credited with the following details. Sharing the details to get the payment accounted for in the system. Do let us know in case of any disconnect.</p>\r\n<p>A reply to this email with a confirmation will be highly appreciated. </p>\r\n<table border=\"1\" cellspacing=\"0\" cellpadding=\"6\" style=\"width: 100%; border-collapse: collapse; font-size: 12px; table-layout: fixed; word-wrap: break-word; word-break: break-word; overflow-wrap: anywhere;\">\r\n    <colgroup>\r\n    <col style=\"width: 9%;\">\r\n    <col style=\"width: 7%;\">\r\n    <col style=\"width: 7%;\">\r\n    <col style=\"width: 7%;\">\r\n    <col style=\"width: 7%;\">\r\n    <col style=\"width: 7%;\">\r\n    <col style=\"width: 7%;\">\r\n    <col style=\"width: 7%;\">\r\n    <col style=\"width: 7%;\">\r\n    <col style=\"width: 7%;\">\r\n    <col style=\"width: 7%;\">\r\n    <col style=\"width: 7%;\">\r\n    <col style=\"width: 7%;\">\r\n    <col style=\"width: 7%;\">\r\n    </colgroup>\r\n    <tr style=\"background-color: #f1f4f9; font-weight: bold;\">\r\n        <th style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; text-align: left;\">Client</th>\r\n        <th style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; text-align: left;\">Cust Code</th>\r\n        <th style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; text-align: left;\">Cust Name</th>\r\n        <th style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; text-align: left;\">Invoice No</th>\r\n        <th style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; text-align: left;\">Assignee</th>\r\n        <th style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; text-align: left;\">Manager</th>\r\n        <th style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; text-align: left;\">Invoice Date</th>\r\n        <th style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; text-align: left;\">Invoice Due Date</th>\r\n        <th style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; text-align: left;\">Invoice Value</th>\r\n        <th style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; text-align: left;\">Basic Value</th>\r\n        <th style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; text-align: left;\">Amount Paid</th>\r\n        <th style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; text-align: left;\">Amount Paid-TDS</th>\r\n        <th style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; text-align: left;\">Instrument No</th>\r\n        <th style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; text-align: left;\">Instrument Date</th>\r\n    </tr>\r\n    <#list listOfInvoices as invoiceList>\r\n    <tr>\r\n        <td style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; vertical-align: top;\">${invoiceList.clientName}</td>\r\n        <td style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; vertical-align: top;\">${invoiceList.customerCode}</td>\r\n        <td style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; vertical-align: top;\">${invoiceList.customerName}</td>\r\n        <td style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; vertical-align: top;\">${invoiceList.invoiceNo}</td>\r\n        <td style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; vertical-align: top;\">${invoiceList.assignee}</td>\r\n        <td style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; vertical-align: top;\">${invoiceList.manager}</td>\r\n        <td style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; vertical-align: top;\">${invoiceList.invoiceDate}</td>\r\n        <td style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; vertical-align: top;\">${invoiceList.invoiceDueDate}</td>\r\n        <td style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; vertical-align: top;\">${invoiceList.invoiceValue}</td>\r\n        <td style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; vertical-align: top;\">${invoiceList.basicValue}</td>\r\n        <td style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; vertical-align: top;\">${invoiceList.AmountPaid}</td>\r\n        <td style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; vertical-align: top;\">${invoiceList.tdsAmount}</td>\r\n        <td style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; vertical-align: top;\">${invoiceList.instrumentNo}</td>\r\n        <td style=\"word-break: break-word; overflow-wrap: anywhere; padding: 6px; vertical-align: top;\">${invoiceList.instrumentDate}</td>\r\n    </tr>\r\n    </#list>\r\n</table>\r\n<p>Regards</p>\r\n${userFullName}\r\n</body>\r\n</html>",
